use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input = input.as_array().unwrap();
    let a = input[0].as_str().unwrap();
    let b = input[1].as_str().unwrap();
    let mut set_a = HashSet::new();
    let mut set_b = HashSet::new();
    for c in a.chars() {
        set_a.insert(c);
    }
    for c in b.chars() {
        set_b.insert(c);
    }
    let mut count = 0;
    for c in a.chars() {
        if set_b.contains(&c) {
            count += 1;
        }
    }
    for c in b.chars() {
        if set_a.contains(&c) {
            count += 1;
        }
    }
    Value::Bool(count > 0)
}
